/*
 * Heating Controller – animated scheme (FR-UI-25).
 *
 * Shows the boiler, the supply and return pipes and the radiators of the rooms
 * by floor. Water flows only where it really flows, the valve heads show their
 * position, a phase bar shows Idle -> Valves -> Boiler heats -> Overrun with a
 * countdown, and two short texts say what happens now and next.
 *
 * The card is served by the integration and generated by the service
 * `hydronic_heating.generate_dashboard`, which fills in the entities.
 * Animations use CSS only and stop with prefers-reduced-motion.
 *
 * Options (FR-UI-25): `layout: compact` is lower and without the texts,
 * `show_text`, `show_now`, `show_upcoming`, `upcoming_max`, `show_phases` and
 * `show_outdoor` hide parts. The defaults keep the full scheme.
 */

const TAG = "hydronic-heating-flow-card";
// The integration adds its version to the URL (?v=), which also busts the cache.
const VERSION = new URL(import.meta.url).searchParams.get("v") || "dev";

const TEXTS = {
  cs: {
    boiler: "Kotel",
    now: "Teď",
    next: "Pak",
    nothing_next: "Nic naplánovaného.",
    phases: { idle: "Klid", valves: "Ventily", firing: "Kotel topí", overrun: "Doběh" },
    pre_close: "Zavírají se ventily",
    pre_open: "Otevírají se ventily",
    countdown: {
      start: "kotel zapne za {t}",
      min_on: "min. běh ještě {t}",
      duty: "podle omezení střídy vypne za {t}",
      overrun: "doběh ještě {t}",
      may_start: "kotel může zapnout za {t}",
      recovery: "návrat z poruchy za {t}",
    },
    window: "okno",
    airing: "větrání",
    manual: "ručně",
    running: "běží",
    stopped: "stojí",
    missing: "Chybí nastavení. Kartu vygeneruje služba hydronic_heating.generate_dashboard.",
    editor: {
      title: "Nadpis",
      layout: "Rozložení",
      full: "Celé (schéma, fáze a texty)",
      compact: "Kompaktní (nižší, bez textů)",
      show_now: "Text Teď",
      show_upcoming: "Text Pak",
      upcoming_max: "Nejvýš řádků v Pak (prázdné = všechny)",
      show_phases: "Pruh fází a odpočet",
      show_outdoor: "Venkovní teplota",
      entities: "Entity a patra vkládá služba generate_dashboard. Kartu zkopírujte z pohledu Schéma.",
    },
  },
  en: {
    boiler: "Boiler",
    now: "Now",
    next: "Next",
    nothing_next: "Nothing planned.",
    phases: { idle: "Idle", valves: "Valves", firing: "Boiler heats", overrun: "Overrun" },
    pre_close: "Valves closing",
    pre_open: "Valves opening",
    countdown: {
      start: "boiler starts in {t}",
      min_on: "minimum run {t} more",
      duty: "duty limit stops it in {t}",
      overrun: "overrun {t} more",
      may_start: "boiler may start in {t}",
      recovery: "back from the fault in {t}",
    },
    window: "window",
    airing: "airing",
    manual: "manual",
    running: "running",
    stopped: "stopped",
    missing: "Configuration missing. The service hydronic_heating.generate_dashboard creates the card.",
    editor: {
      title: "Title",
      layout: "Layout",
      full: "Full (scheme, phases and texts)",
      compact: "Compact (lower, without texts)",
      show_now: "Now text",
      show_upcoming: "Next text",
      upcoming_max: "At most lines in Next (empty = all)",
      show_phases: "Phase bar and countdown",
      show_outdoor: "Outdoor temperature",
      entities: "The service generate_dashboard fills in the entities and floors. Copy the card from the Scheme view.",
    },
  },
};

// Boiler reason -> step of the phase bar.
const STEP = {
  pre_close: "valves",
  pre_open: "valves",
  firing_demand: "firing",
  firing_manual: "firing",
  firing_frost: "firing",
  min_on_hold: "firing",
  overrun: "overrun",
};
// Reasons that hold or block the boiler; shown as a chip next to the phases.
const BLOCKS = new Set([
  "startup",
  "off",
  "summer",
  "window_block",
  "no_flow_hold",
  "min_off_hold",
  "max_starts_hold",
  "duty_hold",
  "fault_safe",
  "fault_recovery",
]);
const COUNTDOWN = {
  pre_close: "start",
  pre_open: "start",
  min_on_hold: "min_on",
  overrun: "overrun",
  min_off_hold: "may_start",
  max_starts_hold: "may_start",
  duty_hold: "may_start",
  fault_recovery: "recovery",
};
const FLOWING_VALVES = new Set(["open", "opening", "closing", "mixed"]);
const WARM_PIPE = 35;
const FIRE =
  "M17.66 11.2C17.43 10.9 17.15 10.64 16.89 10.38C16.22 9.78 15.46 9.35 14.82 8.72C13.33 " +
  "7.26 13 4.85 13.95 3C13 3.23 12.17 3.75 11.46 4.32C8.87 6.4 7.85 10.07 9.07 13.22C9.11 " +
  "13.32 9.15 13.42 9.15 13.55C9.15 13.77 9 13.97 8.8 14.05C8.57 14.15 8.33 14.09 8.14 " +
  "13.93C8.08 13.88 8.04 13.83 8 13.76C6.87 12.33 6.69 10.28 7.45 8.64C5.78 10 4.87 12.3 " +
  "5 14.47C5.06 14.97 5.12 15.47 5.29 15.97C5.43 16.57 5.7 17.17 6 17.7C7.08 19.43 8.95 " +
  "20.67 10.96 20.92C13.1 21.19 15.39 20.8 17.03 19.32C18.86 17.66 19.5 15 18.56 12.72L18.43 " +
  "12.46C18.22 12 17.66 11.2 17.66 11.2Z";

// Geometry of a floor row and of the boiler, relative to their top; the
// compact layout is lower for the main dashboard.
const GEOMETRY = {
  full: {
    row: 150, floor: 14, supply: 30, valve: 36, body: 56, bodyH: 40, ret: 108, label: 128, info: 144,
    boiler: 124, caseY: 16, caseW: 108, caseH: 90, flameX: 37, flameY: 33, flame: 2.1, textX: 132,
    textY: [40, 60, 78],
  },
  compact: {
    row: 116, floor: 12, supply: 22, valve: 27, body: 42, bodyH: 30, ret: 82, label: 98, info: 112,
    boiler: 88, caseY: 12, caseW: 84, caseH: 66, flameX: 31, flameY: 26, flame: 1.6, textX: 108,
    textY: [30, 48, 64],
  },
};
const LEFT = 64;
const SUPPLY_X = 24;
const RETURN_X = 44;
const MIN_SLOT = 96;

const STYLE = `
  :host { display: block; }
  ha-card { display: block; padding: 12px 12px 14px; overflow: hidden; }
  .head { display: flex; justify-content: space-between; align-items: baseline; margin: 0 4px 6px; }
  .title { font-size: 1.15em; font-weight: 500; color: var(--primary-text-color); }
  .outdoor { color: var(--secondary-text-color); font-size: 0.95em; }
  svg { display: block; width: 100%; height: auto; overflow: visible; }
  text { fill: var(--primary-text-color); font-family: var(--ha-font-family-body, inherit); }
  .label { font-size: 13px; font-weight: 500; }
  .info, .floor, .muted { font-size: 12px; fill: var(--secondary-text-color); }
  .floor { font-weight: 600; letter-spacing: 0.04em; }
  .floor.airable { cursor: pointer; text-decoration: underline dotted; }
  .floor.airing { fill: var(--hh-open); }
  .pipe { fill: none; stroke-width: 4; stroke-linecap: round; stroke-linejoin: round; }
  .pipe.supply { stroke: var(--hh-hot); opacity: 0.25; }
  .pipe.return { stroke: var(--hh-cold); opacity: 0.25; }
  .flow { fill: none; stroke-width: 4; stroke-linecap: round; stroke-dasharray: 6 12;
    opacity: 0; transition: opacity 0.6s; }
  .flow.supply { stroke: var(--hh-hot); }
  .flow.return { stroke: var(--hh-cold); }
  .flow.on { opacity: 1; animation: hh-flow 1.1s linear infinite; }
  .flow.on.slow { animation-duration: 3.2s; }
  @keyframes hh-flow { to { stroke-dashoffset: -18; } }
  .radiator rect.body { fill: var(--hh-idle); opacity: 0.35; transition: fill 1s, opacity 1s; }
  .radiator.warm rect.body { fill: var(--hh-hot); opacity: 0.85; }
  .radiator line { stroke: var(--card-background-color, #fff); stroke-width: 2; opacity: 0.6; }
  .head-valve { stroke: var(--card-background-color, #fff); stroke-width: 1.5; }
  .head-valve.open { fill: var(--hh-open); }
  .head-valve.closed, .head-valve.unknown { fill: var(--hh-idle); }
  .head-valve.moving { fill: var(--hh-moving); animation: hh-blink 1s ease-in-out infinite; }
  @keyframes hh-blink { 50% { opacity: 0.25; } }
  .room { cursor: pointer; }
  .room:focus { outline: none; }
  .room:focus-visible .body { stroke: var(--primary-color); stroke-width: 2; }
  .boiler { cursor: pointer; }
  .boiler rect.case { fill: var(--secondary-background-color, #f2f2f2);
    stroke: var(--hh-idle); stroke-width: 2; transition: stroke 0.6s; }
  .boiler.burning rect.case { stroke: var(--hh-hot); }
  .boiler .glow { fill: var(--hh-hot); opacity: 0; }
  .boiler.burning .glow { opacity: 0.18; animation: hh-glow 2.4s ease-in-out infinite; }
  @keyframes hh-glow { 50% { opacity: 0.32; } }
  .boiler .flame { fill: var(--hh-idle); transform-box: fill-box; transform-origin: 50% 100%; }
  .boiler.burning .flame { fill: var(--hh-hot); animation: hh-flicker 0.9s ease-in-out infinite; }
  @keyframes hh-flicker { 50% { transform: scale(0.92, 1.06); } }
  .phases { display: flex; gap: 4px; margin: 10px 2px 4px; flex-wrap: wrap; }
  .step { flex: 1 1 0; min-width: 64px; text-align: center; padding: 6px 4px; border-radius: 8px;
    font-size: 0.85em; color: var(--secondary-text-color);
    background: var(--secondary-background-color, rgba(127,127,127,0.1)); transition: all 0.4s; }
  .step.active { color: var(--text-primary-color, #fff); background: var(--hh-step, var(--hh-hot));
    font-weight: 600; }
  .step.active.valves { --hh-step: var(--hh-moving); color: #000; }
  .step.active.overrun { --hh-step: var(--hh-cold); }
  .step.active.idle { --hh-step: var(--hh-idle); color: var(--primary-text-color); }
  .status { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; margin: 6px 4px 0;
    min-height: 1.4em; font-size: 0.95em; }
  .chip { padding: 2px 10px; border-radius: 12px; font-size: 0.85em; font-weight: 500;
    background: var(--hh-moving); color: #000; }
  .chip.fault { background: var(--error-color, #db4437); color: #fff; }
  .countdown { color: var(--primary-text-color); font-variant-numeric: tabular-nums; }
  .texts { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin: 12px 4px 0; }
  .texts h4 { margin: 0 0 4px; font-size: 0.9em; text-transform: uppercase; letter-spacing: 0.06em;
    color: var(--secondary-text-color); font-weight: 600; }
  .texts p { margin: 0 0 4px; line-height: 1.4; }
  .texts ul { margin: 0; padding-left: 18px; line-height: 1.45; }
  @media (max-width: 600px) { .texts { grid-template-columns: 1fr; } }
  @media (prefers-reduced-motion: reduce) {
    .flow.on, .head-valve.moving, .boiler.burning .flame, .boiler.burning .glow {
      animation: none; }
  }
  .texts.single { grid-template-columns: 1fr; }
  ha-card.compact { padding: 8px 10px 10px; }
  ha-card.compact .phases { margin-top: 6px; }
  .missing { padding: 16px; color: var(--secondary-text-color); }
`;

class HydronicHeatingFlowCard extends HTMLElement {
  constructor() {
    super();
    this.attachShadow({ mode: "open" });
    this._layoutKey = "";
    this._width = 0;
  }

  static getStubConfig() {
    return { floors: [] };
  }

  setConfig(config) {
    if (!config || typeof config !== "object") throw new Error("Invalid configuration");
    this._config = config;
    this._layoutKey = "";
    if (this._hass) this._render();
  }

  set hass(hass) {
    this._hass = hass;
    this._render();
  }

  static async getConfigElement() {
    await loadForm();
    return document.createElement(`${TAG}-editor`);
  }

  getCardSize() {
    // Units of 50 px: the scheme, then the phases and the texts.
    const opt = options(this._config);
    const g = GEOMETRY[opt.layout];
    const rows = this._layoutRows?.length || this._config?.floors?.length || 1;
    const px = rows * g.row + g.boiler + (opt.phases ? 70 : 0) + (opt.now || opt.upcoming ? 120 : 0);
    return Math.ceil(px / 50);
  }

  getGridOptions() {
    return { columns: "full", rows: "auto" };
  }

  connectedCallback() {
    this._timer = window.setInterval(() => this._tick(), 1000);
    if (!this._observer && "ResizeObserver" in window) {
      this._observer = new ResizeObserver((entries) => {
        const width = Math.round(entries[0].contentRect.width);
        if (Math.abs(width - this._width) > 8) {
          this._width = width;
          this._render();
        }
      });
      this._observer.observe(this);
    }
  }

  disconnectedCallback() {
    window.clearInterval(this._timer);
    if (this._observer) {
      this._observer.disconnect();
      this._observer = undefined;
    }
  }

  // --- helpers -------------------------------------------------------------

  get _t() {
    const lang = (this._hass?.locale?.language || this._hass?.language || "en").slice(0, 2);
    return TEXTS[lang] || TEXTS.en;
  }

  _state(entityId) {
    return entityId ? this._hass?.states?.[entityId] : undefined;
  }

  _format(entityId) {
    const state = this._state(entityId);
    if (!state || ["unknown", "unavailable"].includes(state.state)) return "–";
    try {
      return this._hass.formatEntityState(state);
    } catch (err) {
      return state.state;
    }
  }

  _rooms() {
    const floors = Array.isArray(this._config?.floors) ? this._config.floors : [];
    return floors.flatMap((floor) => floor.rooms || []);
  }

  _moreInfo(entityId) {
    if (!entityId) return;
    const event = new Event("hass-more-info", { bubbles: true, composed: true });
    event.detail = { entityId };
    this.dispatchEvent(event);
  }

  // --- layout --------------------------------------------------------------

  _rows(width) {
    const slots = Math.max(1, Math.floor((width - LEFT - 8) / MIN_SLOT));
    const rows = [];
    for (const floor of this._config.floors || []) {
      const rooms = floor.rooms || [];
      for (let i = 0; i < Math.max(rooms.length, 1); i += slots) {
        rows.push({
          floor: i === 0 ? floor.name || "" : "",
          ventilation: i === 0 ? floor.ventilation : undefined,
          rooms: rooms.slice(i, i + slots),
        });
      }
    }
    return { rows, slots };
  }

  _build(g) {
    const width = Math.max(300, this._width || this.clientWidth || 900);
    const { rows, slots } = this._rows(width);
    const slot = Math.max(MIN_SLOT, (width - LEFT - 8) / Math.max(1, Math.min(slots,
      Math.max(...rows.map((r) => r.rooms.length), 1))));
    const height = rows.length * g.row + g.boiler;
    const boilerY = rows.length * g.row;
    const parts = [];
    // Risers in segments: segment r carries the water of row r and the rows above.
    rows.forEach((_, r) => {
      const last = r === rows.length - 1;
      const below = last ? boilerY + g.caseY : (r + 1) * g.row + g.supply;
      parts.push(this._pipe(`M${SUPPLY_X} ${below} V${r * g.row + g.supply}`, "supply", `riser-s-${r}`));
      const under = last ? boilerY + g.caseY : (r + 1) * g.row + g.ret;
      parts.push(this._pipe(`M${RETURN_X} ${r * g.row + g.ret} V${under}`, "return", `riser-r-${r}`));
    });
    rows.forEach((row, r) => {
      const y0 = r * g.row;
      if (row.floor) {
        // Tap the floor to air it (FR-WIN-07); the text shows until when it airs.
        const role = row.ventilation ? ` role="button" tabindex="0"` : "";
        parts.push(`<text class="floor${row.ventilation ? " airable" : ""}" data-floor="${r}"
          x="${LEFT}" y="${y0 + g.floor}"${role}>${esc(row.floor)}</text>`);
      }
      if (!row.rooms.length) return;
      const xs = row.rooms.map((_, i) => LEFT + slot * (i + 0.5));
      const rw = Math.min(64, slot - 30);
      // Main pipes in segments: segment i feeds radiator i and the ones behind it.
      xs.forEach((x, i) => {
        const from = i === 0 ? SUPPLY_X : xs[i - 1] - rw / 2 + 8;
        parts.push(this._pipe(`M${from} ${y0 + g.supply} H${x - rw / 2 + 8}`, "supply", `main-s-${r}-${i}`));
        const to = i === 0 ? RETURN_X : xs[i - 1] + rw / 2 - 8;
        parts.push(this._pipe(`M${x + rw / 2 - 8} ${y0 + g.ret} H${to}`, "return", `main-r-${r}-${i}`));
      });
      row.rooms.forEach((room, i) => {
        parts.push(this._room(g, room, xs[i], y0, rw, slot, `${r}-${i}`));
      });
    });
    parts.push(this._boiler(g, boilerY));
    return { svg: `<svg viewBox="0 0 ${width} ${height}" width="${width}" height="${height}"
      role="img">${parts.join("")}</svg>`, rows };
  }

  _pipe(d, kind, id) {
    return `<path class="pipe ${kind}" d="${d}"/>` +
      `<path class="flow ${kind}" data-flow="${id}" d="${d}"/>`;
  }

  _room(g, room, cx, y0, rw, slot, id) {
    const left = cx - rw / 2;
    const sx = left + 8;
    const rx = left + rw - 8;
    const bottom = y0 + g.body + g.bodyH;
    const fins = [];
    for (let x = left + 10; x < left + rw - 6; x += 10) {
      fins.push(`<line x1="${x}" y1="${y0 + g.body + 4}" x2="${x}" y2="${bottom - 4}"/>`);
    }
    const name = clip(room.name || "", Math.floor(slot / 7.2));
    return `
      <g class="room" data-room="${id}" tabindex="0" role="button"
         aria-label="${esc(room.name || "")}">
        ${this._pipe(`M${sx} ${y0 + g.supply} V${y0 + g.body}`, "supply", `branch-s-${id}`)}
        ${this._pipe(`M${rx} ${bottom} V${y0 + g.ret}`, "return", `branch-r-${id}`)}
        <g class="radiator" data-radiator="${id}">
          <rect class="body" x="${left}" y="${y0 + g.body}" width="${rw}" height="${g.bodyH}" rx="5"/>
          ${fins.join("")}
        </g>
        <rect class="head-valve unknown" data-valve="${id}" x="${sx - 7}" y="${y0 + g.valve}"
              width="14" height="12" rx="3"/>
        <text class="label" x="${cx}" y="${y0 + g.label}" text-anchor="middle">${esc(name)}</text>
        <text class="info" data-info="${id}" x="${cx}" y="${y0 + g.info}"
              text-anchor="middle"></text>
      </g>`;
  }

  _boiler(g, y) {
    const [label, temp, state] = g.textY;
    return `
      <g class="boiler" data-boiler tabindex="0" role="button" aria-label="${this._t.boiler}">
        <rect class="glow" x="2" y="${y + g.caseY - 6}" width="${g.caseW + 12}"
              height="${g.caseH + 12}" rx="16"/>
        <rect class="case" x="8" y="${y + g.caseY}" width="${g.caseW}" height="${g.caseH}" rx="12"/>
        <g transform="translate(${g.flameX} ${y + g.flameY}) scale(${g.flame})">
          <path class="flame" d="${FIRE}"/></g>
        <text class="label" x="${g.textX}" y="${y + label}">${this._t.boiler}</text>
        <text class="info" data-boiler-temp x="${g.textX}" y="${y + temp}"></text>
        <text class="info" data-boiler-state x="${g.textX}" y="${y + state}"></text>
      </g>`;
  }

  // --- render --------------------------------------------------------------

  _render() {
    if (!this._config || !this._hass) return;
    if (!this._rooms().length) {
      this.shadowRoot.innerHTML = `<style>${STYLE}</style>
        <ha-card><div class="missing">${this._t.missing}</div></ha-card>`;
      this._layoutKey = "";
      return;
    }
    const width = Math.round(this._width || this.clientWidth || 900);
    const key = `${width}|${JSON.stringify(this._config)}|${this._t.boiler}`;
    if (key !== this._layoutKey) {
      this._layoutKey = key;
      const opt = options(this._config);
      const { svg, rows } = this._build(GEOMETRY[opt.layout]);
      this._layoutRows = rows;
      const t = this._t;
      const title = this._config.title ? `<div class="title">${esc(this._config.title)}</div>` : "<div></div>";
      const head = this._config.title || opt.outdoor
        ? `<div class="head">${title}${opt.outdoor ? `<div class="outdoor" data-outdoor></div>` : ""}</div>`
        : "";
      const phases = opt.phases
        ? `<div class="phases">
            ${["idle", "valves", "firing", "overrun"]
              .map((s) => `<div class="step ${s}" data-step="${s}">${t.phases[s]}</div>`)
              .join("")}
          </div>
          <div class="status"><span class="chip" data-chip hidden></span>
            <span class="countdown" data-countdown></span></div>`
        : "";
      const columns = [
        opt.now ? `<div><h4>${t.now}</h4><div data-now></div></div>` : "",
        opt.upcoming ? `<div><h4>${t.next}</h4><ul data-next></ul></div>` : "",
      ].filter(Boolean);
      const texts = columns.length
        ? `<div class="texts${columns.length === 1 ? " single" : ""}">${columns.join("")}</div>`
        : "";
      this.shadowRoot.innerHTML = `
        <style>${STYLE}</style>
        <ha-card class="${opt.layout}" style="--hh-hot: var(--deep-orange-color, #ff6f22);
          --hh-cold: var(--blue-color, #2196f3); --hh-open: var(--cyan-color, #00bcd4);
          --hh-moving: var(--amber-color, #ffc107); --hh-idle: var(--grey-color, #9e9e9e);">
          ${head}
          ${svg}
          ${phases}
          ${texts}
        </ha-card>`;
      this._bind();
    }
    this._update();
  }

  _bind() {
    const root = this.shadowRoot;
    const rooms = this._layoutRooms();
    root.querySelectorAll("[data-room]").forEach((el) => {
      const room = rooms[el.dataset.room];
      const open = () => this._moreInfo(room?.climate);
      el.addEventListener("click", open);
      el.addEventListener("keydown", (ev) => {
        if (ev.key === "Enter" || ev.key === " ") open();
      });
    });
    root.querySelectorAll("[data-floor]").forEach((el) => {
      const row = (this._layoutRows || [])[el.dataset.floor];
      if (!row?.ventilation) return;
      const toggle = () => {
        const on = this._state(row.ventilation)?.state === "on";
        this._hass.callService("switch", on ? "turn_off" : "turn_on", {
          entity_id: row.ventilation,
        });
      };
      el.addEventListener("click", toggle);
      el.addEventListener("keydown", (ev) => {
        if (ev.key === "Enter" || ev.key === " ") toggle();
      });
    });
    const boiler = root.querySelector("[data-boiler]");
    const openBoiler = () => this._moreInfo(this._config.reason || this._config.boiler);
    boiler?.addEventListener("click", openBoiler);
    boiler?.addEventListener("keydown", (ev) => {
      if (ev.key === "Enter" || ev.key === " ") openBoiler();
    });
  }

  _layoutRooms() {
    const map = {};
    (this._layoutRows || []).forEach((row, r) =>
      row.rooms.forEach((room, i) => {
        map[`${r}-${i}`] = room;
      }),
    );
    return map;
  }

  _update() {
    const root = this.shadowRoot;
    const cfg = this._config;
    const t = this._t;
    const boiler = this._state(cfg.boiler);
    const reason = this._state(cfg.reason);
    const phase = boiler?.attributes?.phase || "idle";
    const pump = phase === "firing" || phase === "overrun";
    const actual = this._state(cfg.actual);
    const burning = actual ? actual.state === "on" : boiler?.state === "on" && phase === "firing";
    const slow = phase === "overrun";
    const flowing = {};

    for (const [id, room] of Object.entries(this._layoutRooms())) {
      const valve = this._state(room.valve)?.state || "unknown";
      const pipe = Number(this._state(room.pipe)?.state);
      const flows = pump && FLOWING_VALVES.has(valve);
      flowing[id] = flows;
      const head = root.querySelector(`[data-valve="${id}"]`);
      if (head) {
        const cls = valve === "open" ? "open" : valve === "closed" ? "closed"
          : FLOWING_VALVES.has(valve) ? "moving" : "unknown";
        head.setAttribute("class", `head-valve ${cls}`);
      }
      const radiator = root.querySelector(`[data-radiator="${id}"]`);
      const warm = flows || (Number.isFinite(pipe) && pipe >= WARM_PIPE);
      radiator?.setAttribute("class", `radiator${warm ? " warm" : ""}`);
      this._flow(`branch-s-${id}`, flows, slow);
      this._flow(`branch-r-${id}`, flows, slow);
      const info = root.querySelector(`[data-info="${id}"]`);
      if (info) info.textContent = this._roomInfo(room);
    }
    const rows = this._layoutRows || [];
    rows.forEach((row, r) => {
      const label = root.querySelector(`[data-floor="${r}"]`);
      if (!label || !row.floor) return;
      const airing = this._state(row.ventilation);
      label.textContent = airing?.state === "on"
        ? `${row.floor} · ${t.airing} ${airing.attributes.ends || ""}`.trim()
        : row.floor;
      label.classList.toggle("airing", airing?.state === "on");
    });
    const rowFlows = rows.map((row, r) => row.rooms.map((_, i) => flowing[`${r}-${i}`]));
    rowFlows.forEach((flows, r) => {
      flows.forEach((_, i) => {
        const beyond = flows.slice(i).some(Boolean);
        this._flow(`main-s-${r}-${i}`, beyond, slow);
        this._flow(`main-r-${r}-${i}`, beyond, slow);
      });
      // The lowest riser segment always runs with the pump (bypass); upper ones
      // only while a room on their floor or above takes water.
      const above = rowFlows.slice(0, r + 1).some((f) => f.some(Boolean));
      const on = pump && (above || r === rows.length - 1);
      this._flow(`riser-s-${r}`, on, slow);
      this._flow(`riser-r-${r}`, on, slow);
    });

    const boilerEl = root.querySelector("[data-boiler]");
    boilerEl?.setAttribute("class", `boiler${burning ? " burning" : ""}`);
    const temp = root.querySelector("[data-boiler-temp]");
    if (temp) temp.textContent = cfg.flow ? this._format(cfg.flow) : "";
    const state = root.querySelector("[data-boiler-state]");
    if (state) state.textContent = burning ? t.running : t.stopped;
    const outdoor = root.querySelector("[data-outdoor]");
    if (outdoor) outdoor.textContent = cfg.outdoor ? this._format(cfg.outdoor) : "";

    // Phase bar and the hold or block next to it.
    const code = reason?.state || "idle";
    const step = STEP[code] || "idle";
    root.querySelectorAll("[data-step]").forEach((el) => {
      el.classList.toggle("active", el.dataset.step === step);
      if (el.dataset.step === "valves") {
        el.textContent = code === "pre_close" ? t.pre_close : code === "pre_open" ? t.pre_open
          : t.phases.valves;
      }
    });
    const chip = root.querySelector("[data-chip]");
    if (chip) {
      const blocked = BLOCKS.has(code) || code === "min_on_hold";
      chip.hidden = !blocked;
      chip.classList.toggle("fault", code.startsWith("fault"));
      chip.textContent = blocked ? this._format(cfg.reason) : "";
    }
    const nowEl = root.querySelector("[data-now]");
    if (nowEl) {
      const lines = reason?.attributes?.now || [reason?.attributes?.detail || ""];
      nowEl.innerHTML = lines.filter(Boolean).map((line) => `<p>${esc(line)}</p>`).join("");
    }
    const nextEl = root.querySelector("[data-next]");
    if (nextEl) {
      const items = (reason?.attributes?.upcoming || []).slice(0, options(cfg).upcomingMax);
      nextEl.innerHTML = items.length
        ? items.map((item) => `<li>${esc(item.text)}</li>`).join("")
        : `<li>${esc(t.nothing_next)}</li>`;
    }
    this._tick();
  }

  _roomInfo(room) {
    const climate = this._state(room.climate);
    const parts = [];
    if (room.demand) parts.push(this._format(room.demand));
    if (climate?.attributes?.current_temperature != null) {
      const value = climate.attributes.current_temperature;
      parts.push(`${Number(value).toLocaleString(this._hass?.locale?.language || undefined, {
        maximumFractionDigits: 1,
      })} °C`);
    }
    const window = climate?.attributes?.window_state;
    if (window === "open_detected" || window === "open_manual") parts.push(this._t.airing);
    else if (window && window !== "closed") parts.push(this._t.window);
    else if (climate?.state === "heat") parts.push(this._t.manual);
    return parts.join(" · ");
  }

  _flow(id, on, slow) {
    const el = this.shadowRoot.querySelector(`[data-flow="${id}"]`);
    if (!el) return;
    el.classList.toggle("on", Boolean(on));
    el.classList.toggle("slow", Boolean(on && slow));
  }

  _tick() {
    const el = this.shadowRoot?.querySelector("[data-countdown]");
    if (!el || !this._hass) return;
    const reason = this._state(this._config.reason);
    const code = reason?.state;
    let key = COUNTDOWN[code];
    let until = reason?.attributes?.until;
    if (STEP[code] === "firing" && !key) {
      // Firing on demand: the end of the minimum run, else the duty stop.
      const minOn = (reason?.attributes?.upcoming || []).find((e) => e.kind === "min_on_end");
      if (minOn) {
        key = "min_on";
        until = minOn.at;
      } else if (until) {
        key = "duty";
      }
    }
    const left = until ? (new Date(until).getTime() - Date.now()) / 1000 : NaN;
    el.textContent = key && left > 0 ? this._t.countdown[key].replace("{t}", clock(left)) : "";
  }
}

// Editor fields -> keys of `options()`.
const FIELDS = {
  layout: "layout",
  show_now: "now",
  show_upcoming: "upcoming",
  upcoming_max: "upcomingMax",
  show_phases: "phases",
  show_outdoor: "outdoor",
};

/*
 * Visual editor of the display options. The entities and floors stay as the
 * generator wrote them; the editor only changes the options.
 */
class HydronicHeatingFlowCardEditor extends HTMLElement {
  setConfig(config) {
    this._config = config || {};
    this._render();
  }

  set hass(hass) {
    this._hass = hass;
    this._render();
  }

  get _t() {
    const lang = (this._hass?.locale?.language || this._hass?.language || "en").slice(0, 2);
    return (TEXTS[lang] || TEXTS.en).editor;
  }

  _render() {
    if (!this._config || !this._hass) return;
    if (!this._form) {
      this._note = document.createElement("p");
      this._note.style.cssText = "margin: 0 0 12px; color: var(--secondary-text-color);";
      this._form = document.createElement("ha-form");
      this._form.computeLabel = (schema) => this._t[schema.name] || schema.name;
      this._form.addEventListener("value-changed", (ev) => this._changed(ev.detail.value || {}));
      this.append(this._note, this._form);
    }
    const t = this._t;
    const opt = options(this._config);
    this._note.textContent = t.entities;
    this._note.hidden = Array.isArray(this._config.floors) && this._config.floors.length > 0;
    this._data = { title: this._config.title || "" };
    for (const [field, key] of Object.entries(FIELDS)) this._data[field] = opt[key];
    this._form.hass = this._hass;
    this._form.data = this._data;
    this._form.schema = [
      { name: "title", selector: { text: {} } },
      {
        name: "layout",
        selector: {
          select: {
            mode: "dropdown",
            options: [
              { value: "full", label: t.full },
              { value: "compact", label: t.compact },
            ],
          },
        },
      },
      {
        type: "grid",
        name: "",
        schema: ["show_now", "show_upcoming", "show_phases", "show_outdoor"].map((name) => ({
          name,
          selector: { boolean: {} },
        })),
      },
      { name: "upcoming_max", selector: { number: { min: 1, max: 8, mode: "box" } } },
    ];
  }

  _changed(value) {
    // Only the changed fields go to the config, and a value equal to its
    // default is left out, so the YAML stays short.
    const config = { ...this._config };
    for (const field of new Set([...Object.keys(this._data), ...Object.keys(value)])) {
      const val = value[field];
      if (val === this._data[field] || (val == null && this._data[field] == null)) continue;
      delete config[field];
      if (field === "title") {
        if (val) config.title = val;
      } else if (FIELDS[field] && val != null && val !== "" && val !== options(config)[FIELDS[field]]) {
        config[field] = val;
      }
    }
    this._config = config;
    this.dispatchEvent(
      new CustomEvent("config-changed", { detail: { config }, bubbles: true, composed: true }),
    );
    this._render();
  }
}

// The editor of the built-in button card brings ha-form with it.
async function loadForm() {
  if (customElements.get("ha-form")) return;
  try {
    await customElements.get("hui-button-card")?.getConfigElement();
  } catch (err) {
    // Without ha-form the card still works from YAML.
  }
}

// Display options with their defaults (FR-UI-25). A part's own switch wins over
// `show_text`, which wins over the layout; compact hides the texts.
function options(config) {
  const cfg = config || {};
  const layout = cfg.layout === "compact" ? "compact" : "full";
  const flag = (value, fallback) => (typeof value === "boolean" ? value : fallback);
  const text = flag(cfg.show_text, layout === "full");
  const max = Number(cfg.upcoming_max);
  return {
    layout,
    now: flag(cfg.show_now, text),
    upcoming: flag(cfg.show_upcoming, text),
    phases: flag(cfg.show_phases, true),
    outdoor: flag(cfg.show_outdoor, true),
    upcomingMax: Number.isInteger(max) && max > 0 ? max : undefined,
  };
}

function clock(seconds) {
  const s = Math.max(0, Math.round(seconds));
  const h = Math.floor(s / 3600);
  const m = Math.floor((s % 3600) / 60);
  const rest = String(s % 60).padStart(2, "0");
  return h ? `${h}:${String(m).padStart(2, "0")}:${rest}` : `${m}:${rest}`;
}

function clip(text, max) {
  return text.length > max ? `${text.slice(0, Math.max(1, max - 1))}…` : text;
}

function esc(value) {
  return String(value).replace(/[&<>"']/g, (c) => ({
    "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;",
  })[c]);
}

if (!customElements.get(TAG)) {
  customElements.define(TAG, HydronicHeatingFlowCard);
  customElements.define(`${TAG}-editor`, HydronicHeatingFlowCardEditor);
  window.customCards = window.customCards || [];
  window.customCards.push({
    type: TAG,
    name: "Heating Controller – scheme",
    description: "Animated scheme of the boiler, pipes, valves and radiators.",
    documentationURL: "https://github.com/elvisek2020/hacs-heating_system#karta-na-jiném-dashboardu",
  });
  console.info(`%c HYDRONIC-HEATING-FLOW-CARD %c ${VERSION} `,
    "color: #fff; background: #ff6f22; font-weight: 700;",
    "color: #ff6f22; background: #fff; font-weight: 700;");
}
